return [
  {
    json: {
      // Look here! We are sending it straight to your local Home Assistant IP and port (8123)
      url: "http://10.234.113.183:8123/api/states",
    }
  }
];

// n8n Code node
// Reads ALL incoming items (each Home Assistant entity as one item)
// Returns ONE item with json object in the required structure

const entities = items.map(i => i.json);

// -------- Helpers --------
const byId = (id) => entities.find(e => e.entity_id === id);

const toBool = (v) => (v === 'on' ? true : v === 'off' ? false : null);

const toNum = (v) => {
  if (v === null || v === undefined || v === 'unknown' || v === 'unavailable' || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

const cleanTextState = (v) => {
  if (v === null || v === undefined) return null;
  const s = String(v).trim();
  if (!s || s === 'unknown' || s === 'unavailable') return null;
  return s;
};

const toIsoNoMs = (s) => {
  if (!s || s === 'unknown' || s === 'unavailable') return null;
  // Handles "2026-03-02 00:00:00" and ISO strings
  const normalized = String(s).replace(' ', 'T');
  const d = new Date(normalized);
  if (isNaN(d.getTime())) return null;
  return d.toISOString().replace(/\.\d{3}Z$/, '');
};

const hhmmFromDate = (d) =>
  `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;

// -------- Extract entities --------
const zoneHome = byId('zone.home');
const priorityMode = byId('input_select.priority_mode');

const cropType = byId('input_text.crop_type');
const growthStage = byId('input_text.growth_stage');

const soil = byId('input_number.soit_moisture') || byId('input_number.soil_moisture'); // typo-safe
const temp = byId('input_number.temperature');
const airHum = byId('input_number.air_humidity');
const lumi = byId('input_number.luminosity');

const pumpState = byId('input_boolean.pump_physical_state');
const fanState = byId('input_boolean.fan_physical_state');
const pumpOverride = byId('input_boolean.pump_manual_override');
const fanOverride = byId('input_boolean.fan_manual_override');

const pumpExecAt = byId('input_datetime.pump_excecute_at');
const pumpExecUntil = byId('input_datetime.pump_excecute_until');
const fanExecAt = byId('input_datetime.fan_excecute_at');
const fanExecUntil = byId('input_datetime.fan_excecute_until');

const now = new Date();

// -------- Build output --------
const result = {
  meta: {
    run_id: `${Math.random().toString(16).slice(2, 8)}-${Math.random().toString(16).slice(2, 14)}`,
    triggered_at: now.toISOString().replace(/\.\d{3}Z$/, ''),
    mode: cleanTextState(priorityMode?.state)
  },
  location: {
    latitude: zoneHome?.attributes?.latitude ?? null,
    longitude: zoneHome?.attributes?.longitude ?? null,
    timezone: 'Africa/Algiers'
  },
  crop: {
    type: cleanTextState(cropType?.state),
    growth_stage: cleanTextState(growthStage?.state)
  },
  sensors: {
    soil_moisture: toNum(soil?.state),
    temperature: toNum(temp?.state),
    air_humidity: toNum(airHum?.state),
    luminosity: toNum(lumi?.state),
    time_of_day: hhmmFromDate(now)
  },
  actuators: {
    pump: {
      // ✅ fixed: actual entity id
      entity_id: pumpState?.entity_id ?? null,
      physical_state: cleanTextState(pumpState?.state),
      classification: "",
      skipped: false,
      manual_override: toBool(pumpOverride?.state),
      timer: {
        active: !!toIsoNoMs(pumpExecUntil?.state),
        duration_minutes: null,
        execute_until: toIsoNoMs(pumpExecUntil?.state)
      },
      delay: {
        active: !!toIsoNoMs(pumpExecAt?.state),
        execute_at: toIsoNoMs(pumpExecAt?.state)
      }
    },
    fan: {
      // ✅ fixed: actual entity id
      entity_id: fanState?.entity_id ?? null,
      physical_state: cleanTextState(fanState?.state),
      classification: "",
      skipped: null,
      manual_override: toBool(fanOverride?.state),
      timer: {
        active: !!toIsoNoMs(fanExecUntil?.state),
        duration_minutes: null,
        execute_until: toIsoNoMs(fanExecUntil?.state)
      },
      delay: {
        active: !!toIsoNoMs(fanExecAt?.state),
        execute_at: toIsoNoMs(fanExecAt?.state)
      }
    }
  },
  weather: null,
  history: null,
  extra: {
    recommendations: [],
    warnings: []
  }
};

// n8n requires each item's json to be an object
return [{ json: result }];
